                exterior[r][c] = True
                q.append((r, c))
    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))
    while q:
        r, c = q.popleft()
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and not exterior[nr][nc]:
                exterior[nr][nc] = True
                q.append((nr, nc))

    # Label orthogonally connected 1-components.
    labels = [[-1] * w for _ in range(h)]
